const HEX64_RE = /^[0-9a-f]{64}$/;
const COMMIT_RE = /^[0-9a-f]{40}$/;
const BATCH_ID_RE = /^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$/;
const RUN_ID_RE = /^autopilot-\d{8}T\d{6}Z-[0-9a-f]{6}$/;
const REQUEST_ID_RE = /^[0-9a-f]{16}$/;
