  if (!Array.isArray(kind.argv) || kind.argv.length === 0 || kind.argv.length > 32) fail(`${where}.argv is not a list of 1 to 32 words`);
  if (!Array.isArray(kind.slots)) fail(`${where}.slots is not a list`);
